149	<script>
150	import router from "@system.router"
151	import storage from "@system.storage"
152	import { getWeather } from "../../common/services"
153	import { getThemeSync, setTheme } from "../../common/theme"
154	import { getCached, setCache } from "../../common/cache"
155	import { regions } from "../../common/cities"
156	
157	function pad(value) {
158	  return value < 10 ? "0" + value : "" + value
159	}
160	
161	var CITY_STORAGE_KEY = "infoWeatherCity"
162	
163	export default {
164	  private: {
165	    isDark: false,
166	    themeButtonText: "深色模式",
167	    modeLabel: "浅色",
168	    currentTime: "--:--",
169	    selectedCity: "北京",
170	    showCityPicker: false,
171	    pickerLevel: 0,
172	    pickerTitle: "选择地区",
173	    pickerList: [],
174	    regionLabel: "",
175	    provinceLabel: "",
176	    selectedRegionIdx: -1,
177	    selectedProvinceIdx: -1,
178	    expandedAlertIdx: -1,
179	    weatherInfo: {
180	      title: "北京",
181	      subtitle: "正在获取天气...",
182	      message: "--°C",
183	      details: [],
184	      detailsExtra: [],
185	      indexes: [],
186	      forecasts: [],
187	      alerts: []
188	    }
189	  },
190	
191	  onInit() {
192	    this.isDark = getThemeSync()
193	    this.themeButtonText = this.isDark ? "浅色模式" : "深色模式"
194	    this.modeLabel = this.isDark ? "深色" : "浅色"
195	    this.updateClock()
196	    this.loadSavedCity()
197	  },
198	
199	  onShow() {
200	    this.updateClock()
201	  },
202	
203	  updateClock() {
204	    var now = new Date()
205	    this.currentTime = pad(now.getHours()) + ":" + pad(now.getMinutes())
206	  },
207	
208	  toggleTheme() {
209	    this.isDark = !this.isDark
210	    this.themeButtonText = this.isDark ? "浅色模式" : "深色模式"
211	    this.modeLabel = this.isDark ? "深色" : "浅色"
212	    setTheme(this.isDark)
213	  },
214	
215	  goNews() {
216	    router.back()
217	  },
218	
219	  goExpress() {
220	    router.push({ uri: "pages/express" })
221	  },
222	
223	  loadSavedCity() {
224	    var self = this
225	    storage.get({
226	      key: CITY_STORAGE_KEY,
227	      success: function (data) {
228	        if (data) {
229	          self.selectedCity = data
230	        }
231	        self.loadWeatherData()
232	      },
233	      fail: function () {
234	        self.loadWeatherData()
235	      }
236	    })
237	  },
238	
239	  saveCity(city) {
240	    storage.set({
241	      key: CITY_STORAGE_KEY,
242	      value: city
243	    })
244	  },
245	
246	  toggleAlert(idx) {
247	    this.expandedAlertIdx = this.expandedAlertIdx === idx ? -1 : idx
248	  },
249	
250	  openCityPicker() {
251	    this.pickerLevel = 0
252	    this.pickerTitle = "选择地区"
253	    this.regionLabel = ""
254	    this.provinceLabel = ""
255	    this.selectedRegionIdx = -1
256	    this.selectedProvinceIdx = -1
257	    this.pickerList = []
258	    this.showCityPicker = true
259	  },
260	
261	  pickRegion(idx) {
262	    this.selectedRegionIdx = idx
263	    this.regionLabel = regions[idx].name
264	    this.pickerTitle = regions[idx].name
265	    var names = []
266	    var provs = regions[idx].provinces
267	    for (var i = 0; i < provs.length; i++) {
268	      names.push(provs[i].name)
269	    }
270	    this.pickerList = names
271	    this.pickerLevel = 1
272	  },
273	
274	  pickProvince(idx) {
275	    if (this.selectedRegionIdx < 0 || idx < 0) return
276	    var provs = regions[this.selectedRegionIdx].provinces
277	    if (idx >= provs.length) return
278	    this.selectedProvinceIdx = idx
279	    this.provinceLabel = provs[idx].name
280	    this.pickerTitle = this.provinceLabel
281	    this.pickerList = provs[idx].cities
282	    this.pickerLevel = 2
283	  },
284	
285	  pickCity(idx) {
286	    if (idx < 0 || idx >= this.pickerList.length) return
287	    this.selectedCity = this.pickerList[idx]
288	    this.saveCity(this.selectedCity)
289	    this.showCityPicker = false
290	    this.loadWeatherData()
291	  },
292	
293	  pickerBack() {
294	    if (this.pickerLevel === 2) {
295	      this.pickerLevel = 1
296	      this.pickerTitle = this.regionLabel
297	      var provs = regions[this.selectedRegionIdx].provinces
298	      var names = []
299	      for (var i = 0; i < provs.length; i++) {
300	        names.push(provs[i].name)
301	      }
302	      this.pickerList = names
303	    } else if (this.pickerLevel === 1) {
304	      this.pickerLevel = 0
305	      this.pickerTitle = "选择地区"
306	      this.regionLabel = ""
307	      this.provinceLabel = ""
308	      this.selectedRegionIdx = -1
309	      this.pickerList = []
310	    } else {
311	      this.showCityPicker = false
312	    }
313	  },
314	
315	  jumpToRegion() {
316	    this.pickerLevel = 0
317	    this.pickerTitle = "选择地区"
318	    this.regionLabel = ""
319	    this.provinceLabel = ""
320	    this.selectedRegionIdx = -1
321	    this.pickerList = []
322	  },
323	
324	  jumpToProvince() {
325	    if (this.selectedRegionIdx < 0) return
326	    this.pickerLevel = 1
327	    this.pickerTitle = this.regionLabel
328	    var provs = regions[this.selectedRegionIdx].provinces
329	    var names = []
330	    for (var i = 0; i < provs.length; i++) {
331	      names.push(provs[i].name)
332	    }
333	    this.pickerList = names
334	  },
335	
336	  loadWeatherData() {
337	    var city = this.selectedCity
338	    var cacheKey = "weather_" + city
339	    var cached = getCached(cacheKey)
340	    if (cached) {
341	      this.weatherInfo = cached
342	      return
343	    }
344	    getWeather(city).then((info) => {
345	      setCache(cacheKey, info, 10 * 60 * 1000)
346	      this.weatherInfo = info
347	      this.expandedAlertIdx = -1
348	    })
349	  }
350	}
351	</script>
