156	      status: "",
157	      details: []
158	    }
159	  },
160	
161	  onInit() {
162	    this.isDark = getThemeSync()
163	    this.themeButtonText = this.isDark ? "浅色模式" : "深色模式"
164	    this.modeLabel = this.isDark ? "深色" : "浅色"
165	    this.updateClock()
166	    this.loadSavedList()
167	  },
168	
169	  onShow() {
170	    this.updateClock()
171	  },
172	
173	  updateClock() {
174	    var now = new Date()
175	    this.currentTime = pad(now.getHours()) + ":" + pad(now.getMinutes())
176	  },
177	
178	  toggleTheme() {
179	    this.isDark = !this.isDark
180	    this.themeButtonText = this.isDark ? "浅色模式" : "深色模式"
181	    this.modeLabel = this.isDark ? "深色" : "浅色"
182	    setTheme(this.isDark)
183	  },
184	
185	  goNews() {
186	    router.back()
187	  },
188	
189	  goWeather() {
190	    router.push({ uri: "pages/weather" })
191	  },
192	
193	  toggleKeyboard() {
194	    this.showKeyboard = !this.showKeyboard
195	  },
196	
197	  onKeyTap(key) {
198	    if (key === "DEL") {
199	      if (this.trackingNo.length > 0) {
200	        this.trackingNo = this.trackingNo.substring(0, this.trackingNo.length - 1)
201	      }
202	    } else if (key === "CLR") {
203	      this.trackingNo = ""
204	    } else if (key === "OK") {
205	      this.showKeyboard = false
206	    } else {
207	      this.trackingNo += key
208	    }
209	  },
210	
211	  queryExpress() {
212	    var trackingNo = this.trackingNo.trim()
213	    if (!trackingNo) {
214	      this.expressInfo = {
215	        title: "请输入运单号",
216	        subtitle: "tmini-快递查询",
217	        message: "请在下方输入框输入快递运单号进行查询",
218	        status: "",
219	        details: []
220	      }
221	      return
222	    }
223	
224	    this.showKeyboard = false
225	    this.expressLoading = true
226	    this.expressStateText = "正在查询快递信息"
227	
228	    getExpress(trackingNo).then((info) => {
229	      this.expressInfo = info
230	      this.expressLoading = false
231	      this.saveToList(trackingNo)
232	    }).catch((err) => {
233	      this.expressLoading = false
234	      this.hasError = true
235	      this.errorText = "快递查询失败: " + err.message
236	    })
237	  },
238	
239	  loadSavedList() {
240	    this.savedList = []
241	  },
242	
243	  saveToList(trackingNo) {
244	    if (!trackingNo) return
245	    var list = this.savedList.filter(function (item) { return item !== trackingNo })
246	    list.unshift(trackingNo)
247	    if (list.length > 10) list = list.slice(0, 10)
248	    this.savedList = list
249	  },
250	
251	  removeSaved(index) {
252	    var list = this.savedList.filter(function (_, i) { return i !== index })
253	    this.savedList = list
254	  },
255	
256	  loadSaved(item) {
257	    this.trackingNo = item
258	    this.queryExpress()
259	  }
260	}
